/* Beyond storefront enhancement layer. Device-local preview; live commerce requires WooCommerce. */
const storeData=window.BEYOND_STORES;
const storeStatus={open:['Now open','Come experience your fit. Contact the store for current opening hours.'],closed:['Temporarily closed','Closed for an upgrade. Contact support for reopening updates.'],soon:['Coming soon','A new Beyond experience is on its way. Opening date to be announced.']};
let modalReturn=null,slideTimer=null,slideIndex=0,galleryIndex=0,galleryProduct=null,quickProduct=null,quickVariant=null,checkoutStep=0,checkoutDraft={},revealObserver=null;
const readLocal=(key,fallback)=>{try{return JSON.parse(localStorage.getItem('beyond-'+key))||fallback}catch{return fallback}};
const writeLocal=(key,value)=>localStorage.setItem('beyond-'+key,JSON.stringify(value));
const wa=(message,phone='8318595521')=>'https://wa.me/91'+phone+'?text='+encodeURIComponent(message);
const available=p=>p.variants.some(v=>v.stock&&v.price>0);
const ratingFor=p=>{const rs=reviews.filter(r=>r.product===p.id);return rs.length?(rs.reduce((a,r)=>a+Number(r.rating),0)/rs.length).toFixed(1):null};
const bagCount=()=>cart.reduce((n,x)=>n+x.qty,0);
function closeOverlay(){const d=$('#beyond-dialog');if(d){d.close();d.remove()}document.body.classList.remove('dialog-open');modalReturn?.focus?.();modalReturn=null;quickProduct=null;quickVariant=null;}
function openOverlay(title,body,kind='standard'){closeOverlay();modalReturn=document.activeElement;const d=document.createElement('dialog');d.id='beyond-dialog';d.className='lux-dialog '+kind;d.setAttribute('aria-labelledby','dialog-title');d.innerHTML=`<div class="dialog-shell"><div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button data-close aria-label="Close dialog" class="close-button">×</button></div><div class="dialog-body">${body}</div></div>`;document.body.append(d);document.body.classList.add('dialog-open');d.showModal();d.addEventListener('cancel',e=>{e.preventDefault();closeOverlay()});d.addEventListener('click',e=>{if(e.target===d)closeOverlay()});d.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const items=[...d.querySelectorAll('a,button,input,select,textarea,[tabindex="0"]')].filter(x=>!x.disabled&&x.offsetParent!==null);let first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}});d.querySelector('input:not([type=radio]):not([type=checkbox]),button')?.focus();return d;}
function track(type,data={}){window.dataLayer=window.dataLayer||[];window.dataLayer.push({event:'beyond_preview_'+type,...data,preview:true})}
header=function(){const path=location.pathname;return `<div class="announcement"><span>BEYOND SIZE. BEYOND LIMITS.</span><a href="/stores/">Experience Beyond in store</a></div><header id="lux-header"><div class="header-inner"><div class="header-left"><button class="icon menu" id="menu-toggle" aria-label="Open navigation" aria-expanded="false"><svg viewBox="0 0 24 24">${icons.menu}</svg></button><nav aria-label="Main navigation"><div class="nav-group"><a class="nav-link ${path.startsWith('/shop')?'active':''}" href="/shop/">Shop</a><div class="mega"><div><h3>Discover Beyond</h3><a href="/new-arrivals/">New arrivals edit</a><a href="/best-sellers/">Bestsellers edit</a><a href="/collections/">Featured collections</a><a href="/shop-by-size/">Shop by size</a></div><div><h3>Shop by category</h3>${categories.map(c=>`<a href="/product-category/${catSlug(c)}/">${c}</a>`).join('')}</div><div><h3>Made for you</h3><a href="/men/">Men's collection</a><a href="/women/">Women's collection</a><a href="/fit-profile/">Find my fit</a></div></div></div><a class="nav-link ${path.startsWith('/men')?'active':''}" href="/men/">Men</a><a class="nav-link ${path.startsWith('/women')?'active':''}" href="/women/">Women</a><a class="nav-link" href="/about/">Our story</a></nav></div><a class="brand-center" href="/" aria-label="Beyond Plus Size home"><img class="logo" src="/assets/logo.png" alt="Beyond The Plus Size Store"></a><div class="tools"><a class="icon" href="/search/" data-open-search aria-label="Search products"><svg viewBox="0 0 24 24">${icons.search}</svg></a><a class="icon store-icon" href="/stores/" aria-label="Find a store"><svg viewBox="0 0 24 24"><path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></svg></a>${icon('heart','/wishlist/','Wishlist')}${icon('user','/account/','My account')}<a class="icon cart-icon" href="/cart/" data-open-bag aria-label="Shopping bag"><svg viewBox="0 0 24 24">${icons.bag}</svg><span id="cart-count">${bagCount()}</span></a></div></div></header><div class="mobile-nav" id="mobile-nav"><div class="eyebrow">EXPLORE BEYOND</div>${[['New arrivals','/new-arrivals/'],['Shop all','/shop/'],['Men','/men/'],['Women','/women/'],['Featured collections','/collections/'],['Shop by size','/shop-by-size/'],['Find a store','/stores/'],['Our story','/about/'],['The journal','/blog/'],['Contact','/contact/']].map(([t,u])=>`<a href="${u}">${t}<span>＋</span></a>`).join('')}</div>`};
card=function(p){const rating=ratingFor(p),inStock=available(p);return `<article class="lux-product"><div class="product-image"><a class="product-image-link" href="/product/${p.slug}/">${img(p)}${p.gallery?.length>1?`<img class="hover-image" src="${esc(p.gallery[1])}" alt="${esc(p.name)} alternate view" loading="lazy" onerror="this.remove()">`:''}</a>${p.regular>p.price&&p.price>0?`<span class="badge sale-badge">−${Math.round((1-p.price/p.regular)*100)}%</span>`:!inStock?'<span class="badge">Ask about availability</span>':''}<button class="wish ${wishlist.includes(p.id)?'selected':''}" data-wish="${p.id}" aria-label="${wishlist.includes(p.id)?'Remove from':'Add to'} wishlist">${wishlist.includes(p.id)?'♥':'♡'}</button><div class="product-actions"><button data-quick="${p.id}">Quick view</button><button class="primary" data-quick-add="${p.id}" ${!inStock?'aria-label="Check availability"':''}>${inStock?'Choose size':'Ask about stock'}</button></div></div><div class="product-info"><div class="product-meta"><span class="type">${p.category}</span><span class="card-rating">${rating?`★ ${rating} <small>preview</small>`:'No reviews yet'}</span></div><a href="/product/${p.slug}/"><h3>${esc(p.name)}</h3></a><div class="price">${p.price>0?'From '+money(p.price):'Price to be confirmed'}${p.regular>p.price&&p.price>0?`<del>${money(p.regular)}</del>`:''}</div><div class="card-fit-row"><span class="sizes">${p.sizeAttribute?.toLowerCase().includes('brand')?'Brand sizes: ':''}${p.variants.filter(v=>v.stock&&v.price>0).slice(0,4).map(v=>esc(v.size)).join(' · ')}${p.variants.filter(v=>v.stock).length>4?' + more':''}</span><span class="color-label">${esc(p.color||'')}</span></div><div class="card-stock">${inStock?'Available sizes in preview':'Contact for availability'}</div></div></article>`};
function curated(kind){if(kind==='new')return [...products].reverse().filter(available);if(kind==='best')return products.filter(p=>available(p)&&/shirt|trouser|polo/i.test(p.name));if(kind==='trend')return products.filter(p=>available(p)&&/textured|jacquard|printed|graphic/i.test(p.name));return products.filter(available)}
function productSection(title,sub,list,path,eyebrow='THE BEYOND EDIT',limit=4){return `<section class="reveal"><div class="section-head"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div><a class="text-link" href="${path}">Explore the edit</a></div><div class="product-grid">${list.slice(0,limit).map(card).join('')}</div></section>`}
function storeMini(s){return `<a class="mini-store" href="/stores/?store=${s.id}"><span class="status-pill ${s.status}">${storeStatus[s.status][0]}</span><h3>${s.name}</h3><p>${s.city}</p><span class="text-link">${s.status==='open'?'Visit your store':'See what’s next'}</span></a>`}
home=function(){const heroProducts=[products.find(p=>/Urban Teal/i.test(p.name)),products.find(p=>/Cream.*Trouser|Trouser.*Cream/i.test(p.name))||products.find(p=>p.category==='Trousers'),products.find(p=>/Polo/i.test(p.name))].filter(Boolean);const slides=[['Style, without<br><em>size limits.</em>','Thoughtful fits. Beautiful fabrics. A little more you.','Everyday, elevated.',heroProducts[0]],['Your day.<br><em>Your way.</em>','Comfort that goes beyond the working week.','The essentials edit.',heroProducts[1]],['Make room for<br><em>great style.</em>','Discover colour, character and your next favourite.','Relax into your style.',heroProducts[2]]];let recent=readLocal('recent',[]).map(id=>products.find(p=>p.id===id)).filter(Boolean);return `<div class="lux-hero" role="region" aria-roledescription="carousel" aria-label="Beyond featured collections"><div class="hero-slides">${slides.map(([h,p,label,product],i)=>`<article class="hero-slide ${i===0?'is-active':''}" data-slide="${i}" aria-hidden="${i!==0}"><div class="hero-copy"><div class="eyebrow">BEYOND / THE PLUS SIZE STORE</div><h1>${h}</h1><p>${p}</p><div class="hero-ctas"><a class="button primary" href="/men/">Shop men</a><a class="button" href="/women/">Explore women</a></div><a class="hero-arrivals text-link" href="/new-arrivals/">Discover the new arrivals edit</a></div><div class="hero-photo">${img(product)}<a class="hero-tag" href="/product/${product.slug}/"><span>${label}</span><strong>Discover this style</strong></a><span class="hero-image-note">BEYOND / ${String(i+1).padStart(2,'0')}</span></div></article>`).join('')}</div><div class="slide-controls"><button data-slide-prev aria-label="Previous slide">‹</button><div class="slide-dots">${slides.map((_,i)=>`<button data-slide-to="${i}" class="${i===0?'active':''}" aria-label="Show slide ${i+1}" aria-pressed="${i===0}"></button>`).join('')}</div><button data-slide-next aria-label="Next slide">›</button><button id="slide-pause" aria-label="Pause slideshow">Ⅱ</button><span class="slide-count">01 / 03</span></div></div><div class="trust"><div><span>✓</span> Fits designed around you</div><div><span>◇</span> Considered fabric choices</div><div><span>↔</span> Product-specific sizes</div><div><span>♡</span> Real people. Personal help.</div></div><div class="wrap"><section class="size-strip reveal"><div><div class="eyebrow">YOUR SIZE. YOUR STYLE.</div><h2>Start with your fit.</h2></div><div class="size-links">${['2XL','3XL','4XL','5XL','6XL','7XL','8XL'].map(s=>`<a href="/shop/?size=${s}">${s}</a>`).join('')}<a class="size-guide-link" href="/fit-profile/">Find my fit</a></div></section>${productSection('Fresh perspective. Effortless style.','The latest catalogue edit. Pick something that feels like you.',curated('new'),'/new-arrivals/','NEW ARRIVALS',4)}<section class="reveal campaign-duo"><div class="campaign-men"><div class="campaign-image">${img(products.find(p=>p.category==='Shirts'))}</div><div class="campaign-copy"><div class="eyebrow">THE MEN’S COLLECTION</div><h2>Made for<br>your everyday.</h2><a class="button" href="/men/">Discover menswear</a></div></div><div class="campaign-women"><div class="eyebrow">THE NEXT CHAPTER</div><h2>Women.<br>Style on<br>your terms.</h2><p>Thoughtful collections are on their way. Tell us what you would love to wear.</p><a class="button primary" href="/women/">Explore women's categories</a><span class="campaign-note">Women's inventory coming to the catalogue</span></div></section>${productSection('A little texture. A lot of character.','Prints and considered details for the way you dress.',curated('trend'),'/collections/','TRENDING STYLE EDIT',4)}<section class="reveal"><div class="section-head"><div><div class="eyebrow">EXPLORE YOUR WARDROBE</div><h2>Good style, from the ground up.</h2></div><a class="text-link" href="/shop/">Shop every category</a></div><div class="category-carousel">${categories.map(c=>{const p=products.find(p=>p.category===c);return `<a class="category-tile" href="/product-category/${catSlug(c)}/">${img(p)}<div><h3>${c}</h3><span>${products.filter(p=>p.category===c).length} styles</span></div></a>`}).join('')}</div></section>${productSection('The pieces you’ll keep coming back to.','Our essentials edit — selected for versatile, everyday dressing.',curated('best'),'/best-sellers/','BESTSELLERS EDIT · CURATED PREVIEW',4)}<section class="reveal store-experience"><div><div class="eyebrow">THE BEYOND STORE EXPERIENCE</div><h2>Find your fit.<br>In real life.</h2><p>Feel the fabric. Try something new. Our Lucknow stores are ready to welcome you.</p><a class="button primary" href="/stores/">Find a Beyond store</a><div class="store-mini-row">${storeData.slice(0,2).map(storeMini).join('')}</div></div><div class="map-preview"><iframe title="Wave Mall Lucknow map preview" loading="lazy" referrerpolicy="no-referrer-when-downgrade" src="https://www.google.com/maps?q=${encodeURIComponent(storeData[0].address)}&output=embed"></iframe><a class="map-caption" href="/stores/">Wave Mall · Lucknow <span>View all stores</span></a></div></section><section class="reveal"><div class="section-head"><div><div class="eyebrow">MORE BEYOND, CLOSER TO YOU</div><h2>A new chapter is coming.</h2></div><a class="text-link" href="/stores/">Store updates</a></div><div class="coming-grid">${storeData.slice(2).map(storeMini).join('')}</div></section><section class="reveal fit-banner"><div><div class="eyebrow">FIT IS PERSONAL</div><h2>A little guidance.<br>A lot more confidence.</h2><p>Save your fit preferences and ask our team for product measurements.</p></div><div><button class="button primary" data-size-guide>What's my size?</button><a class="button" href="/fit-profile/">Create a fit profile</a></div></section><section class="reveal"><div class="section-head"><div><div class="eyebrow">FROM OUR COMMUNITY</div><h2>Good fit. Honest feedback.</h2><p>Feedback supplied from the existing Beyond website.</p></div><a class="text-link" href="/reviews/">Share your experience</a></div><div class="review-grid">${[['Tarun Saxena','These cream trousers are exceptionally comfortable and have a premium feel.'],['Shishir Hegde','Excellent sky blue cotton shirt. The fit is precise, and the fabric is incredibly soft on the skin.'],['Nischal Gowda','This aqua blue t-shirt is perfect for casual weekend wear.']].map(([n,t])=>`<figure class="quote-card"><span class="quote-mark">“</span><blockquote>${t}</blockquote><figcaption>${n}<small>Supplied website feedback · purchase not verified here</small></figcaption></figure>`).join('')}</div></section>${recent.length?productSection('Still thinking about it?','Pick up where you left off.',recent,'/recently-viewed/','RECENTLY VIEWED',4):''}<section class="reveal"><div class="section-head"><div><div class="eyebrow">STAY CONNECTED / @BEYONDPLUSSIZEOFFICIAL</div><h2>Style, beyond the store.</h2><p>Follow Beyond for collection updates and styling inspiration.</p></div><a class="text-link" href="https://www.instagram.com/beyondplussizeofficial/" target="_blank" rel="noopener">Follow on Instagram</a></div><div class="social-collection">${curated('trend').slice(4,8).map(p=>`<a href="/product/${p.slug}/">${img(p)}<span>From the Beyond collection</span></a>`).join('')}</div></section></div>`};
function setSlide(i){const slides=[...document.querySelectorAll('.hero-slide')];if(!slides.length)return;slideIndex=(i+slides.length)%slides.length;slides.forEach((s,n)=>{s.classList.toggle('is-active',n===slideIndex);s.setAttribute('aria-hidden',n!==slideIndex);s.inert=n!==slideIndex});document.querySelectorAll('[data-slide-to]').forEach((b,n)=>{b.classList.toggle('active',n===slideIndex);b.setAttribute('aria-pressed',n===slideIndex)});$('.slide-count').textContent=String(slideIndex+1).padStart(2,'0')+' / '+String(slides.length).padStart(2,'0')}
function startSlides(){clearInterval(slideTimer);slideTimer=null;if(!$('.lux-hero'))return;slideIndex=0;setSlide(0);if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)slideTimer=setInterval(()=>{if(!document.hidden&&!$('#beyond-dialog'))setSlide(slideIndex+1)},6500)}
function slidePause(){if(slideTimer){clearInterval(slideTimer);slideTimer=null;$('#slide-pause').textContent='▷';$('#slide-pause').setAttribute('aria-label','Play slideshow')}else{slideTimer=setInterval(()=>setSlide(slideIndex+1),6500);$('#slide-pause').textContent='Ⅱ';$('#slide-pause').setAttribute('aria-label','Pause slideshow')}}
function quickView(id){const p=products.find(p=>p.id===id);if(!p)return;let v=p.variants.find(v=>v.stock&&v.price>0)||p.variants[0];const rating=ratingFor(p);openOverlay('A closer look',`<div class="quick-layout"><div class="quick-photos"><img id="quick-image" src="${esc(v.image||p.image)}" alt="${esc(p.name)}"><button class="quick-fullscreen" data-gallery="${p.id}">Expand image</button><div class="quick-thumbs">${(p.gallery||[p.image]).map((u,i)=>`<button data-quick-photo="${esc(u)}" aria-label="View photo ${i+1}"><img src="${esc(u)}" alt="${esc(p.name)} view ${i+1}" loading="lazy"></button>`).join('')}</div></div><div class="quick-info"><div class="eyebrow">${p.category}</div><h3>${esc(p.name)}</h3><div class="price" id="quick-price">${money(v.price)}${v.regular>v.price&&v.price>0?`<del>${money(v.regular)}</del>`:''}</div><p class="muted">${rating?'★ '+rating+' · preview reviews':'No verified reviews in this preview'}</p><p>${esc(p.short||p.description).slice(0,260)}</p><div class="quick-color"><span>Colour: ${esc(p.color)}</span><small>Identified from product title</small></div><div class="purchase-size-label"><strong>Select ${esc(p.sizeAttribute||'size')}</strong><button class="inline-link" data-size-guide>Size help</button></div><div class="options">${p.variants.map(v=>`<button data-quick-variant="${v.id}" class="${v.id===quickDefault(p).id?'chosen':''}" ${!v.stock||!v.price?'disabled':''}>${esc(v.size)}</button>`).join('')}</div><p id="quick-stock" class="availability">${v.stock&&v.price?'Available in the supplied catalogue':'Contact for price or availability'} · SKU ${esc(v.sku||v.id)}</p><label class="quantity">Quantity <input id="quick-qty" type="number" min="1" max="10" value="1"></label><div class="quick-purchase"><button class="primary" data-add-quick ${!v.stock||!v.price?'disabled':''}>Add to bag</button><button data-buy-quick ${!v.stock||!v.price?'disabled':''}>Buy now</button></div><button class="inline-link" data-wish="${p.id}">${wishlist.includes(p.id)?'Saved to wishlist':'Save to wishlist'}</button><a class="button view-full" href="/product/${p.slug}/">View full product</a><a class="inline-link" target="_blank" rel="noopener" href="${wa('Hi Beyond, I need help with '+p.name+'. Size: '+v.size)}">Ask on WhatsApp</a></div></div>`,'quick-view');quickProduct=p;quickVariant=v;track('quick_view',{item_id:p.id})}
function quickDefault(p){return p.variants.find(v=>v.stock&&v.price>0)||p.variants[0]}
function updateQuickVariant(id){quickVariant=quickProduct.variants.find(v=>v.id===id);if(!quickVariant)return;document.querySelectorAll('[data-quick-variant]').forEach(b=>b.classList.toggle('chosen',b.dataset.quickVariant===id));$('#quick-price').innerHTML=money(quickVariant.price)+(quickVariant.regular>quickVariant.price?`<del>${money(quickVariant.regular)}</del>`:'');$('#quick-stock').textContent=(quickVariant.stock&&quickVariant.price?'Available in catalogue':'Contact for availability')+' · SKU '+(quickVariant.sku||id);$('#quick-image').src=quickVariant.image||quickProduct.image}
function addPreviewProduct(p,v,qty=1,buy=false){if(!v?.stock||!v.price){toast('Please ask our team about this size and price.');return}if(!Number.isInteger(qty)||qty<1||qty>10){toast('Choose a quantity between 1 and 10.');return}let x=cart.find(x=>x.variantId===v.id);if(x)x.qty=Math.min(10,x.qty+qty);else cart.push({productId:p.id,variantId:v.id,qty});save();track('add_to_cart',{item_id:p.id,variant_id:v.id,value:v.price*qty,currency:'INR'});if(buy){closeOverlay();history.pushState({},'','/checkout/');render();scrollTo(0,0)}else{openBag(`${p.name} · ${v.size} added to your bag`);toast('✓ Added to bag')}}
function openBag(message='Your favourites, ready when you are.'){const items=cartItems(),t=totals();openOverlay('Your shopping bag',`<p class="drawer-intro">${esc(message)}</p><div class="notice compact">Preview bag · prices from your WooCommerce export. No real order is placed.</div><div class="drawer-items">${items.length?items.map(x=>`<div class="drawer-item"><a href="/product/${x.p.slug}/">${img(x.p)}</a><div><a href="/product/${x.p.slug}/"><h3>${esc(x.p.name)}</h3></a><p>${esc(x.v.size)} · ${esc(x.p.color||'')}</p><strong>${money(x.v.price*x.qty)}</strong><div class="quantity"><button data-drawer-qty="${x.variantId}" data-delta="-1" aria-label="Decrease quantity">−</button><span>${x.qty}</span><button data-drawer-qty="${x.variantId}" data-delta="1" aria-label="Increase quantity">+</button><button class="inline-link" data-drawer-remove="${x.variantId}">Remove</button><button class="inline-link" data-save-later="${x.variantId}">Save for later</button></div></div></div>`).join(''):'<div class="empty"><h3>Room for something you love.</h3><a class="button primary" href="/shop/">Discover your style</a></div>'}</div>${items.length?`<form id="drawer-coupon" class="coupon-input"><input name="coupon" placeholder="Coupon code" aria-label="Coupon code"><button>Apply</button></form><div class="drawer-totals"><div class="total-row"><span>Subtotal</span><strong>${money(t.subtotal)}</strong></div>${t.discount?`<div class="total-row"><span>Discount</span><span>−${money(t.discount)}</span></div>`:''}<div class="total-row"><strong>Preview total</strong><strong>${money(t.total)}</strong></div><p class="muted">Shipping and taxes are confirmed in the live store. Free-shipping offers differ in the supplied materials.</p><a class="button primary" href="/checkout/">Continue to demo checkout</a><a class="button" href="/cart/">View shopping bag</a></div>`:''}`,'side-drawer');track('view_cart')}
function changeDrawerQty(id,delta){const x=cart.find(x=>x.variantId===id);if(!x)return;x.qty=Math.max(1,Math.min(10,x.qty+delta));save();openBag()}
function applyPreviewCoupon(code){const c=String(code).trim().toUpperCase(),subtotal=totals().subtotal;if((c==='SAVE100'&&subtotal>=1299)||(c==='STYLE300'&&subtotal>=2499)){coupon=c;return true}toast('SAVE100: subtotal ₹1,299+. STYLE300: subtotal ₹2,499+.');return false}
function openSearch(){const recent=readLocal('searches',[]);openOverlay('Find your next favourite.',`<div class="overlay-search-field"><svg viewBox="0 0 24 24">${icons.search}</svg><input id="overlay-search" type="search" placeholder="Try cotton shirts, polos or trousers" aria-label="Search Beyond products" autocomplete="off"><button data-clear-search class="inline-link">Clear</button></div><div class="search-suggestions"><div><span class="eyebrow">POPULAR SEARCHES</span><div>${['Cotton','Polo','Trousers','Printed','Jackets'].map(t=>`<button data-search-term="${t}">${t}</button>`).join('')}</div></div>${recent.length?`<div><span class="eyebrow">YOUR RECENT SEARCHES</span><div>${recent.map(t=>`<button data-search-term="${esc(t)}">${esc(t)}</button>`).join('')}<button class="inline-link" data-clear-recent>Clear history</button></div></div>`:''}</div><div id="overlay-search-count" role="status"></div><div class="search-overlay-results" id="overlay-search-results"></div>`,'search-overlay');searchOverlayResults('');track('search_open')}
function searchOverlayResults(q){let term=q.trim().toLowerCase();const matches=term?products.filter(p=>(p.name+' '+p.category+' '+p.color).toLowerCase().includes(term)):curated('best').slice(0,6);$('#overlay-search-count').textContent=term?(matches.length?matches.length+' matching styles':'No exact match. Try these styles instead.'):'A few favourites to explore';let result=matches.length?matches:curated('best').slice(0,4);$('#overlay-search-results').innerHTML=result.slice(0,12).map(p=>`<article class="search-result"><a href="/product/${p.slug}/">${img(p)}</a><div><small>${p.category}</small><a href="/product/${p.slug}/"><h3>${esc(p.name)}</h3></a><div class="price">${money(p.price)}${p.regular>p.price&&p.price>0?`<del>${money(p.regular)}</del>`:''}</div><button data-quick-add="${p.id}" class="inline-link">${available(p)?'Choose size & add':'Check availability'}</button></div></article>`).join('')+`<a class="button primary" href="/search/?q=${encodeURIComponent(q)}">View search results</a>`}
function rememberSearch(q){if(q.trim().length<2)return;writeLocal('searches',[q.trim(),...readLocal('searches',[]).filter(x=>x!==q.trim())].slice(0,6));track('search',{search_term:q.trim()})}
function openSizeGuide(){openOverlay('Your fit, thoughtfully chosen.',`<div class="size-modal-grid"><div><div class="eyebrow">A LITTLE GUIDANCE</div><h3>Measure a garment you love.</h3><p>Use a soft tape, keep the garment flat and avoid stretching the fabric.</p>${[['Chest','Measure beneath the armholes. Double the flat width for circumference.'],['Waist','Measure around where you wear your trousers. Keep the tape comfortably level.'],['Hip','Measure the fullest part while standing naturally.'],['Length','Measure from the highest shoulder point to the hem.']].map(([t,p])=>`<details open><summary>${t}</summary><p>${p}</p></details>`).join('')}</div><div class="panel"><h3>Size labels are style-specific.</h3><p>Available size variations come from the product catalogue. It does not include a measurement chart, so we won’t guess your recommended size.</p><a class="button primary" href="/fit-profile/">Save your fit profile</a><p><a class="text-link" target="_blank" rel="noopener" href="${wa('Hi Beyond, please help me choose the right size'+(currentProduct?' for '+currentProduct.name:''))}">Still unsure? Ask on WhatsApp</a></p><a class="text-link" href="/size-guide/">Read the complete size guide</a></div></div>`,'size-modal')}
function openGallery(id,index=0){const p=products.find(p=>p.id===id);if(!p)return;galleryProduct=p;galleryIndex=index;openOverlay(p.name,`<div class="gallery-toolbar"><span id="gallery-count"></span><button data-gallery-zoom>Zoom in</button><button data-gallery-prev aria-label="Previous image">‹</button><button data-gallery-next aria-label="Next image">›</button></div><div class="fullscreen-stage" id="gallery-stage"><img id="gallery-photo" alt="${esc(p.name)}"></div><div class="gallery-thumbnails">${(p.gallery||[p.image]).map((u,i)=>`<button data-gallery-index="${i}" aria-label="View image ${i+1}"><img src="${esc(u)}" alt="${esc(p.name)} view ${i+1}" loading="lazy"></button>`).join('')}</div>`,'gallery-modal');galleryProduct=p;galleryIndex=index;showGalleryImage(index);let start=0;$('#gallery-stage').addEventListener('touchstart',e=>{start=e.touches[0].clientX},{passive:true});$('#gallery-stage').addEventListener('touchend',e=>{let diff=e.changedTouches[0].clientX-start;if(Math.abs(diff)>45)showGalleryImage(galleryIndex+(diff<0?1:-1))},{passive:true});$('#gallery-photo').addEventListener('dblclick',toggleGalleryZoom)}
function showGalleryImage(i){if(!galleryProduct)return;let images=galleryProduct.gallery||[galleryProduct.image];galleryIndex=(i+images.length)%images.length;$('#gallery-photo').src=images[galleryIndex];$('#gallery-photo').classList.remove('zoomed');$('#gallery-count').textContent=(galleryIndex+1)+' / '+images.length;document.querySelectorAll('[data-gallery-index]').forEach(b=>b.classList.toggle('chosen',Number(b.dataset.galleryIndex)===galleryIndex))}
function toggleGalleryZoom(){let z=$('#gallery-photo').classList.toggle('zoomed');$('[data-gallery-zoom]').textContent=z?'Zoom out':'Zoom in'}
productPage=function(p){currentProduct=p;selectedVariant=quickDefault(p);const recent=readLocal('recent',[]);writeLocal('recent',[p.id,...recent.filter(id=>id!==p.id)].slice(0,12));const rating=ratingFor(p);return `<div class="wrap content product-content"><div class="breadcrumb"><a href="/">Home</a> / <a href="/men/">Men</a> / <a href="/product-category/${catSlug(p.category)}/">${p.category}</a></div><div class="split product-detail-layout"><div class="product-gallery"><div class="vertical-thumbnails">${(p.gallery||[p.image]).map((u,i)=>`<button data-pdp-photo="${esc(u)}" data-photo-index="${i}" class="${i===0?'chosen':''}" aria-label="Show product image ${i+1}"><img src="${esc(u)}" alt="${esc(p.name)} detail ${i+1}" loading="lazy"></button>`).join('')}</div><div class="main-product-photo"><button data-gallery="${p.id}" class="main-image-button" aria-label="Open fullscreen product gallery"><img class="product-detail-image" src="${esc(selectedVariant.image||p.image)}" alt="${esc(p.name)}"></button><button class="gallery-expand" data-gallery="${p.id}">Expand & zoom</button><div class="photo-nav"><button data-pdp-prev aria-label="Previous product image">‹</button><button data-pdp-next aria-label="Next product image">›</button></div></div></div><div class="product-details"><div class="eyebrow">BEYOND / ${p.category.toUpperCase()}</div><h1>${esc(p.name)}</h1><div class="pdp-rating">${rating?'★ '+rating+' · device-local preview reviews':'Be the first to review this style'} <a href="/reviews/?product=${p.id}" class="text-link">Write a review</a></div><div class="price" id="variant-price">${money(selectedVariant.price)}${selectedVariant.regular>selectedVariant.price&&selectedVariant.price>0?`<del>${money(selectedVariant.regular)}</del>`:''}</div><p class="pdp-short">${esc(p.short||p.description).slice(0,320)}</p><div class="colour-detail"><span>Colour: <strong>${esc(p.color)}</strong></span><small>From product title · see photos for detail</small></div><div class="purchase-size-label"><h3>Select ${esc(p.sizeAttribute||'size')} <span id="selected-size">${esc(selectedVariant.size)}</span></h3><button class="inline-link" data-size-guide>What's my size?</button></div><div class="options">${p.variants.map(v=>`<button data-variant="${v.id}" class="${v.id===selectedVariant.id?'chosen':''}" ${!v.stock||!v.price?'disabled':''} title="${!v.stock||!v.price?'Contact for availability':esc(v.size)}">${esc(v.size)}</button>`).join('')}</div><div class="availability" id="pdp-stock">${selectedVariant.stock&&selectedVariant.price?'Available in supplied catalogue':'Ask about size / price availability'} · SKU ${esc(selectedVariant.sku||selectedVariant.id)}</div><div id="main-purchase" class="main-purchase"><label class="quantity" for="product-qty">Quantity<input id="product-qty" type="number" value="1" min="1" max="10"></label><div class="purchase-buttons"><button class="primary" id="add-cart" ${!selectedVariant.stock||!selectedVariant.price?'disabled':''}>Add to bag</button><button id="buy-now" ${!selectedVariant.stock||!selectedVariant.price?'disabled':''}>Buy now</button></div></div><div class="pdp-secondary"><button class="inline-link" data-wish="${p.id}">${wishlist.includes(p.id)?'Saved to wishlist':'Save to wishlist'}</button><button class="inline-link" data-share-product="${p.id}">Share this style</button><button class="inline-link" data-compare="${p.id}">Compare</button></div><a class="pdp-whatsapp" target="_blank" rel="noopener" id="product-whatsapp" href="${wa('Hi Beyond, I need help with this product: '+p.name+'\nSize: '+selectedVariant.size+'\n'+location.origin+'/product/'+p.slug+'/')}">Ask our fit team on WhatsApp</a><div class="pdp-accordions">${[['Description',p.description||p.short],['Size & fit','Check this style’s size options above. Product measurement charts are not included in the source export. Contact our team for chest, waist, hip and length measurements.'],['Fabric & material','See the product description and garment label for fabric composition. Ask our team if you need more detail.'],['Wash care','Follow the garment care label. Avoid high heat and wash similar colours together unless the label advises otherwise.'],['Shipping','Delivery depends on product availability and your destination PIN code. Confirm charges and timelines with the live store.'],['Returns & exchange','Contact support to confirm eligibility, deadlines and garment-condition requirements.'],['FAQs','Need help choosing a size, checking availability or understanding delivery? Contact +91 8318595521 or visit our help centre.']].map(([t,d],i)=>`<details ${i===0?'open':''}><summary>${t}</summary><p>${esc(d)}</p>${t==='Shipping'?'<a class="text-link" href="/shipping-policy/">Shipping information</a>':t==='Returns & exchange'?'<a class="text-link" href="/return-policy/">Return information</a>':''}</details>`).join('')}</div></div></div><section class="product-reviews-block reveal"><div class="section-head"><div><div class="eyebrow">HONEST FEEDBACK</div><h2>How did it fit?</h2></div><a class="button" href="/reviews/?product=${p.id}">Write a review</a></div>${reviewList(p.id)}</section>${productSection('You may also like.','More styles from this collection.',products.filter(x=>x.id!==p.id&&x.category===p.category),'/product-category/'+catSlug(p.category)+'/','SIMILAR STYLES',4)}${productSection('Complete your look.','Pair your own favourites. Recommendations are based on category, not sales activity.',products.filter(x=>x.id!==p.id&&x.category!==p.category&&available(x)),'/shop/','WARDROBE PAIRINGS',4)}</div><div class="sticky-purchase" id="sticky-purchase"><img src="${esc(p.image)}" alt="${esc(p.name)}"><div><strong>${esc(p.name)}</strong><span id="sticky-size">Size ${esc(selectedVariant.size)}</span></div><span class="sticky-price" id="sticky-price">${money(selectedVariant.price)}</span><button data-sticky-size class="mobile-only">Size</button><button class="primary" data-sticky-add ${!selectedVariant.stock||!selectedVariant.price?'disabled':''}>Add to bag</button><button data-sticky-buy ${!selectedVariant.stock||!selectedVariant.price?'disabled':''}>Buy now</button></div>`};
function syncProductVariant(){if(!currentProduct||!selectedVariant)return;$('#pdp-stock').textContent=(selectedVariant.stock&&selectedVariant.price?'Available in supplied catalogue':'Ask about availability')+' · SKU '+(selectedVariant.sku||selectedVariant.id);$('#sticky-size').textContent='Size '+selectedVariant.size;$('#sticky-price').textContent=money(selectedVariant.price);$('.product-detail-image').src=selectedVariant.image||currentProduct.image;$('#product-whatsapp').href=wa('Hi Beyond, I need help with '+currentProduct.name+'. Size: '+selectedVariant.size);['#add-cart','#buy-now','[data-sticky-add]','[data-sticky-buy]'].forEach(s=>$(s).disabled=!selectedVariant.stock||!selectedVariant.price)}
function productPhoto(i){if(!currentProduct)return;const images=currentProduct.gallery||[currentProduct.image],index=(i+images.length)%images.length;$('.product-detail-image').src=images[index];document.querySelectorAll('[data-pdp-photo]').forEach(b=>b.classList.toggle('chosen',Number(b.dataset.photoIndex)===index));$('.main-image-button').dataset.galleryIndex=String(index)}
function storeCard(s){return `<article class="store-card ${s.status}" id="store-${s.id}"><span class="status-pill ${s.status}">${storeStatus[s.status][0]}</span><h2>${s.name}</h2><span class="store-city">${s.city}</span><p>${s.address}</p><p class="store-status-note">${storeStatus[s.status][1]}</p><div class="store-actions"><button data-store-map="${s.id}">View on map</button><a class="button" href="${s.maps||'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(s.address)}" target="_blank" rel="noopener">Directions</a>${s.phone?`<a class="inline-link" href="tel:+91${s.phone}">Call +91 ${s.phone}</a><a class="inline-link" target="_blank" rel="noopener" href="${wa('Hi Beyond, I would like to ask about '+s.name+' in '+s.city,s.phone)}">WhatsApp store</a>`:''}<a class="inline-link" href="/contact/?topic=store">${s.status==='open'?'Request personal assistance':'Ask for store updates'}</a></div></article>`}
function storesPage(){const requested=new URLSearchParams(location.search).get('store');let chosen=storeData.find(s=>s.id===requested)||storeData[0];return `<div class="wrap">${heading('Find a Beyond store.','Feel the fabric. Find your fit. Experience Beyond in person.')}<div class="store-toolbar"><label><span>Search city or location</span><input class="search-input" id="store-search" placeholder="Lucknow, Wave Mall, Ashiyana…"></label><label><span>Store status</span><select id="store-status"><option value="">All stores</option><option value="open">Now open</option><option value="closed">Temporarily closed</option><option value="soon">Coming soon</option></select></label><button data-location>Use my location</button></div><p id="location-status" class="muted" role="status">Store statuses and addresses are supplied by Beyond. Call to confirm current hours.</p><div class="locator-layout"><div class="store-list" id="store-list">${storeData.map(storeCard).join('')}</div><div class="locator-map"><iframe id="store-map" title="${esc(chosen.name)} map" loading="lazy" referrerpolicy="no-referrer-when-downgrade" src="https://www.google.com/maps?q=${encodeURIComponent(chosen.address)}&output=embed"></iframe><div class="map-store-info" id="map-store-info"><span class="status-pill ${chosen.status}">${storeStatus[chosen.status][0]}</span><h3>${chosen.name} · ${chosen.city}</h3><p>${chosen.address}</p></div><div class="map-location-buttons">${storeData.map(s=>`<button data-store-map="${s.id}">${s.city} · ${s.name}</button>`).join('')}</div></div></div><section></section></div>`}
function filterStores(){let q=$('#store-search').value.toLowerCase(),status=$('#store-status').value;let list=storeData.filter(s=>(s.name+' '+s.city+' '+s.address).toLowerCase().includes(q)&&(!status||s.status===status));$('#store-list').innerHTML=list.length?list.map(storeCard).join(''):'<div class="empty"><h2>No store matches.</h2><p>Try another city or status.</p></div>'}
function chooseStore(id){const s=storeData.find(s=>s.id===id);if(!s)return;$('#store-map').src='https://www.google.com/maps?q='+encodeURIComponent(s.address)+'&output=embed';$('#store-map').title=s.name+' map';$('#map-store-info').innerHTML=`<span class="status-pill ${s.status}">${storeStatus[s.status][0]}</span><h3>${s.name} · ${s.city}</h3><p>${s.address}</p>`;document.querySelectorAll('.store-card').forEach(x=>x.classList.toggle('selected-store',x.id==='store-'+id));$('.locator-map').scrollIntoView({behavior:'smooth',block:'nearest'});track('store_locator',{store_id:id})}
function collectionPage(){return `<div class="wrap">${heading('Considered collections.','A wardrobe for your world, one thoughtful piece at a time.')}<section class="collection-grid">${[['The working week','Shirts','Sharp details. Comfortable silhouettes.'],['Weekend, your way','T-Shirts','A little colour. Plenty of ease.'],['The perfect foundation','Trousers','Build an outfit around your comfort.'],['Layer up beautifully','Jackets','A considered finishing touch.'],['Everyday movement','Track Pants','For your off-duty moments.'],['A little celebration','Ethnic Wear','Dress for the moments that matter.']].map(([t,c,d])=>`<a class="collection-card" href="/product-category/${catSlug(c)}/"><div>${img(products.find(p=>p.category===c))}</div><div><div class="eyebrow">BEYOND / ${c.toUpperCase()}</div><h2>${t}</h2><p>${d}</p><span class="text-link">Discover the collection</span></div></a>`).join('')}</section></div>`}
function sizeShop(){return `<div class="wrap">${heading('Your size is a starting point.','Choose a size to explore available variations. Exact fit varies by style.')}<section class="shop-size-grid">${['2XL','3XL','4XL','5XL','6XL','7XL','8XL'].map(s=>`<a class="size-shop-tile" href="/shop/?size=${s}"><span>YOUR FIT</span><h2>${s}</h2><p>${products.filter(p=>p.variants.some(v=>v.size===s&&v.stock)).length} matching styles</p><span class="text-link">Explore styles</span></a>`).join('')}</section><div class="fit-banner"><h2>Still finding your fit?</h2><button class="primary" data-size-guide>Get size guidance</button></div><section></section></div>`}
function fitProfilePage(){let p=readLocal('fit-profile',{});return `<div class="wrap">${heading('A fit profile, just for you.','Save your preferences on this device and share them with our fit team.')}<div class="split content"><div><div class="eyebrow">OPTIONAL / PERSONAL TO YOU</div><h2>A little detail makes a difference.</h2><p>Your measurements help you have a more useful conversation about fit. They are saved only on this device.</p><div class="notice">The catalogue does not include garment measurement charts. A reliable automated size recommendation is not available yet; our team can help you compare specific styles.</div><details open><summary>How to measure</summary><p>Keep the measuring tape comfortably level. Measure your chest and hips at their fullest point, and your waist where you normally wear your trousers.</p></details><a class="text-link" href="/size-guide/">Read the size guide</a></div><form id="fit-profile-form" class="panel stack"><div class="form-grid">${[['Height (cm)','height'],['Weight (kg)','weight'],['Chest (cm)','chest'],['Waist (cm)','waist'],['Hip (cm)','hip']].map(([t,n])=>`<label class="field">${t}<input name="${n}" type="number" min="20" max="350" step="0.1" value="${esc(p[n]||'')}"></label>`).join('')}<label class="field">Preferred fit<select name="fit">${['Relaxed','Regular','Closer'].map(s=>`<option ${p.fit===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Preferred size<select name="size"><option value="">Not sure yet</option>${['2XL','3XL','4XL','5XL','6XL','7XL','8XL'].map(s=>`<option ${p.size===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Preferred collection<select name="collection">${['Men','Women','Both'].map(s=>`<option ${p.collection===s?'selected':''}>${s}</option>`).join('')}</select></label></div><button class="primary">Save my fit profile</button><button type="button" data-share-fit>Share with WhatsApp support</button><button type="button" class="inline-link" data-clear-fit>Clear saved measurements</button></form></div></div>`}
shop=function(title='Shop all',category=''){const query=new URLSearchParams(location.search);filters={category:category||query.get('category')||'',size:query.get('size')||'',max:Number(query.get('max'))||10000,sort:query.get('sort')||'featured',q:query.get('q')||'',color:query.get('color')||'',stock:query.get('stock')||'',sale:query.get('sale')==='1',gender:query.get('gender')||'men',edit:title.includes('New arrivals')?'new':title.includes('Bestsellers')?'best':''};return `<div class="wrap">${heading(title,filters.edit==='new'?'A fresh catalogue edit. Upload dates are not included, so this view follows reverse catalogue order.':filters.edit==='best'?'A curated essentials edit. Live sales rankings are not available in this preview.':'Discover thoughtful fits, considered details and your next favourite.')}<div class="collection-chips"><a href="/shop/" class="${!filters.category?'selected':''}">All styles</a>${categories.map(c=>`<a class="${filters.category===c?'selected':''}" href="/product-category/${catSlug(c)}/">${c}</a>`).join('')}</div><div class="shop-layout"><aside class="filters advanced-filters" id="filter-panel"><div class="filter-heading"><h2>Refine your edit.</h2><button data-filter-close class="mobile-only close-button" aria-label="Close filters">×</button></div><div><h3>Collection</h3><select id="filter-gender" aria-label="Filter collection"><option value="men">Men</option><option value="women" ${filters.gender==='women'?'selected':''}>Women · coming soon</option></select></div><div><h3>Find your size</h3><div class="filter-sizes">${['2XL','3XL','4XL','5XL','6XL','7XL','8XL'].map(s=>`<button data-filter-size="${s}" class="${filters.size===s?'selected':''}" aria-pressed="${filters.size===s}">${s}</button>`).join('')}</div><select id="filter-size" aria-label="All catalogue size labels"><option value="">Every size</option>${[...new Set(products.flatMap(p=>p.variants.map(v=>v.size)))].sort().map(s=>`<option value="${esc(s)}" ${s===filters.size?'selected':''}>${/^\d+$/.test(s)?'Brand size '+esc(s):esc(s)}</option>`).join('')}</select><button class="inline-link" data-size-guide>Help me find my size</button></div><div><h3>Price range</h3><input type="range" min="500" max="10000" step="100" value="${filters.max}" id="filter-price" aria-label="Maximum price"><div id="price-label">Up to ${money(filters.max)}</div></div><div><h3>Colour</h3><select id="filter-color" aria-label="Filter by colour"><option value="">All colours</option>${[...new Set(products.map(p=>p.color))].sort().map(c=>`<option ${c===filters.color?'selected':''}>${esc(c)}</option>`).join('')}</select><small>Colour names from product titles.</small></div><div><h3>Availability</h3><select id="filter-stock" aria-label="Stock availability"><option value="">All catalogue styles</option><option value="in" ${filters.stock==='in'?'selected':''}>Available sizes only</option><option value="out" ${filters.stock==='out'?'selected':''}>Ask about availability</option></select><label><input type="checkbox" id="filter-sale" ${filters.sale?'checked':''}> On sale</label></div><div><h3>Search this edit</h3><input class="search-input" id="filter-search" placeholder="Style, fabric, colour…" aria-label="Search collection" value="${esc(filters.q)}"></div><button data-filter-reset class="filter-reset">Clear all filters</button></aside><div class="shop-products"><div class="toolbar"><button data-filter-open class="filter-toggle">Refine & filter</button><span id="result-count" role="status"></span><div class="view-sort"><button data-grid="2" class="grid-switch" aria-label="Two-column view">▥</button><button data-grid="3" class="grid-switch" aria-label="Three-column view">▦</button><select id="sort" aria-label="Sort products">${[['featured','Recommended'],['new','Catalogue: latest first'],['low','Price: low to high'],['high','Price: high to low'],['name','Name: A–Z']].map(([v,t])=>`<option value="${v}" ${filters.sort===v?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="active-filters" id="active-filters"></div><div class="product-grid" id="results"></div><div class="pagination" id="pagination"></div></div></div><section></section></div>`};
updateResults=function(){const source=filters.edit?curated(filters.edit):products;let data=source.filter(p=>filters.gender!=='women'&&(!filters.category||p.category===filters.category)&&(!filters.size||p.variants.some(v=>v.size===filters.size&&v.stock&&v.price))&&(p.price<=filters.max||!p.price)&&(!filters.q||(p.name+' '+p.category+' '+p.color).toLowerCase().includes(filters.q.toLowerCase()))&&(!filters.color||p.color===filters.color)&&(!filters.stock||filters.stock==='in'&&available(p)||filters.stock==='out'&&!available(p))&&(!filters.sale||p.price>0&&p.price<p.regular));if(filters.sort==='low')data.sort((a,b)=>(a.price||Infinity)-(b.price||Infinity));if(filters.sort==='high')data.sort((a,b)=>b.price-a.price);if(filters.sort==='name')data.sort((a,b)=>a.name.localeCompare(b.name));if(filters.sort==='new')data.reverse();let pages=Math.max(1,Math.ceil(data.length/12));page=Math.min(page,pages);$('#result-count').textContent=data.length+' styles';$('#results').innerHTML=data.length?data.slice((page-1)*12,page*12).map(card).join(''):`<div class="empty empty-filter"><div class="eyebrow">A FRESH START</div><h2>${filters.gender==='women'?'Women’s inventory is on its way.':'Let’s try another fit.'}</h2><p>${filters.gender==='women'?'Explore the prepared women’s categories, or switch to our men’s collection.':'No styles match your current filters. Clear a filter or try another size.'}</p><button class="primary" data-filter-reset>Reset filters</button></div>`;$('#pagination').innerHTML=pages>1?Array.from({length:pages},(_,i)=>`<button class="${page===i+1?'primary':''}" data-page="${i+1}" aria-label="Page ${i+1}" ${page===i+1?'aria-current="page"':''}>${i+1}</button>`).join(''):'';let chips=[filters.size&&['size',filters.size],filters.color&&['color',filters.color],filters.stock&&['stock',filters.stock==='in'?'Available':'Check availability'],filters.sale&&['sale','On sale'],filters.q&&['q','Search: '+filters.q],filters.max<10000&&['max','Up to '+money(filters.max)]].filter(Boolean);$('#active-filters').innerHTML=chips.map(([k,t])=>`<button data-remove-filter="${k}">${esc(t)} <span>×</span></button>`).join('')+(chips.length?'<button class="inline-link" data-filter-reset>Clear all</button>':'');track('filter',{result_count:data.length})};
function filterRefresh(){page=1;updateResults();const q=new URLSearchParams();for(const [k,v] of Object.entries(filters)){if(['edit','category'].includes(k))continue;if(v&&!(k==='max'&&v===10000)&&!(k==='sort'&&v==='featured')&&!(k==='gender'&&v==='men'))q.set(k,k==='sale'?'1':v)}history.replaceState({},'',location.pathname+(q.size?'?'+q.toString():''));document.querySelectorAll('[data-filter-size]').forEach(b=>{b.classList.toggle('selected',b.dataset.filterSize===filters.size);b.setAttribute('aria-pressed',b.dataset.filterSize===filters.size)});if($('#filter-size'))$('#filter-size').value=filters.size}
function resetFilters(){let category=filters.category,edit=filters.edit;filters={category,edit,size:'',max:10000,sort:'featured',q:'',color:'',stock:'',sale:false,gender:'men'};if($('#filter-size'))$('#filter-size').value='';$('#filter-search').value='';$('#filter-price').value=10000;$('#price-label').textContent='Up to ₹10,000';$('#filter-color').value='';$('#filter-stock').value='';$('#filter-gender').value='men';$('#filter-sale').checked=false;$('#sort').value='featured';filterRefresh()}
const baseCartPage=cartPage;
cartPage=function(){let html=baseCartPage();if(cartItems().length){html=html.replace('<a class="text-link" href="/shop/">Continue shopping</a>','<a class="text-link" href="/shop/">Continue shopping</a><div class="bag-tools"><button data-open-shipping>Check delivery information</button><a class="button" href="/wishlist/">View wishlist</a></div>');html=html.replaceAll('<button data-remove=', '<button data-remove=');html+=`<div class="wrap">${productSection('Something to complete the look.','Recommendations selected by category, not purchase history.',products.filter(p=>available(p)&&!cart.some(x=>x.productId===p.id)).slice(0,4),'/shop/','PAIR YOUR FAVOURITES')}</div>`}return html};
function shippingInfo(){openOverlay('Delivery, made clear.',`<form id="delivery-check" class="stack"><p>Enter your PIN code to prepare a delivery enquiry. This preview cannot verify live serviceability, shipping charges or COD availability.</p><label class="field">Delivery PIN code<input name="pin" pattern="[1-9][0-9]{5}" required maxlength="6" inputmode="numeric" placeholder="e.g. 226017"></label><button class="primary">Check format & contact support</button><div id="delivery-result" role="status"></div><a class="text-link" href="/shipping-policy/">Read shipping information</a></form>`)}
function checkoutFields(){return `<div class="form-grid">${field('First name','first','text',true)}${field('Last name','last','text',true)}${field('Email','email','email',true)}${field('Mobile number','phone','tel',true,'pattern="[6-9][0-9]{9}" title="Enter a 10-digit Indian mobile number"')}${field('Street address','address','text',true,'class="full"')}${field('Apartment / landmark','landmark')}${field('City','city','text',true)}${field('State','state','text',true)}${field('PIN code','pin','text',true,'pattern="[1-9][0-9]{5}" maxlength="6" inputmode="numeric"')}<label class="field full">Delivery instructions<textarea name="notes" placeholder="A landmark or anything helpful for delivery."></textarea></label><label class="full"><input type="checkbox" name="saveAddress"> Save this address on this device</label></div>`}
checkout=function(){if(!cartItems().length)return `<div class="wrap">${heading('Checkout')}<div class="empty"><h2>Your bag is empty.</h2><a class="button primary" href="/shop/">Find your next favourite</a></div></div>`;let addresses=readLocal('addresses',[]);return `<div class="checkout-wrap"><div class="checkout-title"><h1>Your next favourite,<br>one step closer.</h1><a class="text-link" href="/cart/">Back to your bag</a></div><div class="notice">Demo checkout only. No payment is collected and no WooCommerce order is placed.</div><div class="checkout-progress">${['Account','Address','Delivery','Payment'].map((t,i)=>`<button data-checkout-step="${i}" class="${i===checkoutStep?'current':i<checkoutStep?'complete':''}"><span>0${i+1}</span>${t}</button>`).join('')}</div><div class="checkout-layout"><form id="lux-checkout" class="stack"><div class="checkout-step ${checkoutStep===0?'current':''}" data-checkout-panel="0"><div class="eyebrow">01 / ACCOUNT</div><h2>Shop at your own pace.</h2><p>Continue as a guest for this shopping preview. Live account login and WhatsApp OTP require the store’s authentication provider.</p><div class="auth-options"><button type="button" class="primary" data-checkout-next>Continue as preview guest</button><button type="button" data-login>Login / WhatsApp options</button></div></div><div class="checkout-step ${checkoutStep===1?'current':''}" data-checkout-panel="1"><div class="eyebrow">02 / YOUR DETAILS</div><h2>Where should it go?</h2>${addresses.length?`<label class="field saved-address-select">Saved address<select id="saved-address"><option value="">Use a new address</option>${addresses.map((a,i)=>`<option value="${i}">${esc(a.first+' '+a.last+' · '+a.city+' '+a.pin)}</option>`).join('')}</select></label>`:''}${checkoutFields()}<div class="step-actions"><button type="button" data-checkout-back>Back</button><button type="button" class="primary" data-checkout-next>Continue to delivery</button></div></div><div class="checkout-step ${checkoutStep===2?'current':''}" data-checkout-panel="2"><div class="eyebrow">03 / DELIVERY</div><h2>A clear next step.</h2><div id="checkout-address-summary" class="panel"></div><label class="delivery-option"><input type="radio" name="shipping" value="standard" checked><div><strong>Standard delivery · preview</strong><p>The supplied checkout mentions 7–8 days. Final timing, serviceability and charges require store confirmation.</p></div></label><label class="gift-option"><input type="checkbox" name="gift"> This is a gift</label><label class="field">Gift message (optional)<textarea name="giftMessage" placeholder="A little note for someone special."></textarea></label><div class="step-actions"><button type="button" data-checkout-back>Back</button><button type="button" class="primary" data-checkout-next>Review payment options</button></div></div><div class="checkout-step ${checkoutStep===3?'current':''}" data-checkout-panel="3"><div class="eyebrow">04 / PAYMENT & REVIEW</div><h2>One last look.</h2><div class="payment-methods"><label class="payment-option"><input type="radio" name="payment" value="cod" checked><div><strong>Cash on delivery · demo</strong><p>Availability depends on live store rules.</p></div></label>${['UPI','Cards','Net Banking','Wallets'].map(t=>`<div class="payment-option unavailable"><span>${t}</span><small>Requires connected payment gateway</small></div>`).join('')}</div><div class="panel" id="final-address"></div><p>No payment details are requested or stored by this preview.</p><label class="checkout-consent"><input type="checkbox" name="consent" required> I understand this creates only a device-local demo order and accept the <a class="text-link" href="/terms-and-conditions/">preview terms</a>.</label><div class="step-actions"><button type="button" data-checkout-back>Back</button><button type="submit" class="primary">Place demo order</button></div></div></form><aside class="checkout-order"><h2>Your edit.</h2>${cartItems().map(x=>`<div class="checkout-item">${img(x.p)}<div><strong>${esc(x.p.name)}</strong><p>${esc(x.v.size)} × ${x.qty}</p><span>${money(x.v.price*x.qty)}</span></div></div>`).join('')}<div id="checkout-totals">${summary()}</div><div class="checkout-coupon"><input id="checkout-coupon" placeholder="Coupon code" aria-label="Coupon code"><button type="button" data-checkout-coupon>Apply</button></div><p class="checkout-help">Need a hand? <a class="text-link" href="${wa('Hi Beyond, I need help with my shopping bag.')}" target="_blank" rel="noopener">WhatsApp our team</a></p></aside></div></div>`};
function captureCheckout(){const f=$('#lux-checkout');if(!f)return;for(const [k,v] of new FormData(f).entries())checkoutDraft[k]=v;writeLocal('checkout-draft',checkoutDraft)}
function restoreCheckout(){const f=$('#lux-checkout');if(!f)return;checkoutDraft={...readLocal('checkout-draft',{}),...checkoutDraft};for(const [k,v] of Object.entries(checkoutDraft)){const input=f.elements.namedItem(k);if(!input)continue;if(input.type==='checkbox')input.checked=v==='on';else if(input.type!=='radio'&&!(input instanceof RadioNodeList))input.value=v}syncCheckoutAddress()}
function syncCheckoutAddress(){let a=checkoutDraft;let html=a.first?`<strong>${esc(a.first+' '+(a.last||''))}</strong><p>${esc(a.address||'')}<br>${esc(a.city||'')}, ${esc(a.state||'')} ${esc(a.pin||'')}</p><p>${esc(a.phone||'')} · ${esc(a.email||'')}</p><button type="button" class="inline-link" data-checkout-step="1">Edit details</button>`:'<p>Add your contact and delivery details.</p>';if($('#checkout-address-summary'))$('#checkout-address-summary').innerHTML=html;if($('#final-address'))$('#final-address').innerHTML=html}
function checkoutGo(n){if(n>checkoutStep&&checkoutStep===1){let fields=[...document.querySelectorAll('[data-checkout-panel="1"] input')];for(const x of fields)if(!x.checkValidity()){x.reportValidity();return}}if(n>checkoutStep+1)return;captureCheckout();checkoutStep=Math.max(0,Math.min(3,n));document.querySelectorAll('[data-checkout-panel]').forEach(x=>x.classList.toggle('current',Number(x.dataset.checkoutPanel)===checkoutStep));document.querySelectorAll('[data-checkout-step]').forEach(x=>{let i=Number(x.dataset.checkoutStep);x.classList.toggle('current',i===checkoutStep);x.classList.toggle('complete',i<checkoutStep)});syncCheckoutAddress();$('.checkout-progress').scrollIntoView({behavior:'smooth',block:'start'})}
function orderConfirmation(order){return `<div class="wrap content"><div class="order-confirmation"><span class="success-check">✓</span><div class="eyebrow">YOUR DEMO ORDER IS READY</div><h1>Thank you, ${esc(order.customer?.first||'Beyond shopper')}.</h1><p>One thoughtful wardrobe, a little more you.</p><div class="notice">Demo only · no real order, payment or shipment was created.</div><div class="confirmation-meta"><div><small>Order reference</small><strong>${esc(order.id)}</strong></div><div><small>Payment status</small><strong>No payment collected</strong></div><div><small>Delivery estimate</small><strong>To be confirmed by live store</strong></div></div><div class="split"><div class="panel"><h2>Delivery details</h2><p>${esc(order.customer?.first||'')} ${esc(order.customer?.last||'')}<br>${esc(order.customer?.address||'')}<br>${esc(order.customer?.city||'')}, ${esc(order.customer?.state||'')} ${esc(order.customer?.pin||'')}</p></div><div class="panel"><h2>Your edit</h2>${order.items.map(x=>`<div class="total-row"><span>${esc(x.name)} · ${esc(x.size)} × ${x.qty}</span><strong>${money(x.price*x.qty)}</strong></div>`).join('')}<div class="total-row"><strong>Preview total</strong><strong>${money(order.total)}</strong></div></div></div><div class="confirmation-actions"><a class="button primary" href="/track-order/?order=${encodeURIComponent(order.id)}">View demo order status</a><a class="button" href="/shop/">Continue shopping</a><a class="button" href="${wa('Hi Beyond, I need help. Preview reference: '+order.id)}" target="_blank" rel="noopener">Chat on WhatsApp</a></div></div></div>`}
function loginOverlay(){openOverlay('Welcome to Beyond.',`<div class="auth-panel"><div class="eyebrow">BROWSE FREELY. SHOP WITH CONFIDENCE.</div><p>Live customer login, registration, password reset and WhatsApp OTP require the connected WordPress store. This preview does not send OTPs or collect passwords.</p><a class="button primary" target="_blank" rel="noopener" href="${wa('Hi Beyond, I need help with my customer account or WhatsApp login.')}">Continue to WhatsApp support</a><button data-account-profile>Create a device-local shopping profile</button><a class="text-link" href="/account/">Continue to preview account</a><button class="inline-link" data-close>Keep browsing as a guest</button></div>`,'login-modal')}
function accountProfileModal(){const p=readLocal('profile',{});openOverlay('Your shopping profile.',`<form id="profile-form" class="stack"><p>Saved on this device only. This does not register a customer account.</p>${field('Your name','name','text',true)}${field('Email','email','email')}${field('Mobile number','phone','tel')}<button class="primary">Save profile</button></form>`);for(const [k,v] of Object.entries(p)){let x=$('#profile-form').elements.namedItem(k);if(x)x.value=v}}
account=function(){const p=readLocal('profile',{}),orders=readLocal('orders',[]),addresses=readLocal('addresses',[]),fit=readLocal('fit-profile',{});return `<div class="wrap">${heading(p.name?'Welcome back, '+p.name+'.':'Your Beyond, in one place.','A thoughtful space for your shopping preferences and demo orders.')}<div class="notice">Device-local preview account. Real login, orders and WhatsApp verification require WooCommerce integration.</div><div class="account-layout content"><aside class="account-menu">${[['overview','Overview'],['orders','Orders'],['addresses','Saved addresses'],['profile','Personal information'],['fit','Size profile'],['coupons','Coupons'],['support','Returns & support']].map(([k,t],i)=>`<button data-account-tab="${k}" class="${i===0?'selected':''}">${t}</button>`).join('')}<a href="/wishlist/">Wishlist</a><a href="/track-order/">Track a demo order</a><button data-login>Login / WhatsApp help</button></aside><div class="account-content"><section data-account-panel="overview"><div class="account-stats"><div><strong>${orders.length}</strong><span>Demo orders</span></div><div><strong>${wishlist.length}</strong><span>Saved favourites</span></div><div><strong>${addresses.length}</strong><span>Saved addresses</span></div></div><h2>Your next favourite is waiting.</h2><p>Save your preferences, revisit a style and pick up where you left off.</p><div class="account-quick"><a class="button primary" href="/shop/">Discover your style</a><a class="button" href="/recently-viewed/">Recently viewed</a><a class="button" href="/compare/">Product comparison</a></div><button class="inline-link" data-clear-preview>Clear all preview data from this device</button></section><section data-account-panel="orders" hidden><h2>Demo orders</h2>${orders.length?orders.map(o=>`<article class="panel account-order"><div><strong>${esc(o.id)}</strong><span>${esc(new Date(o.date).toLocaleDateString('en-IN'))}</span><span>${money(o.total)}</span></div><p>No real payment or shipment</p>${o.items.map(x=>`<p>${esc(x.name)} · ${esc(x.size)} × ${x.qty}</p>`).join('')}<a class="button" href="/order-confirmation/?order=${encodeURIComponent(o.id)}">View details</a><a class="inline-link" href="/track-order/?order=${encodeURIComponent(o.id)}">View demo status</a></article>`).join(''):'<div class="empty">No demo orders yet.</div>'}</section><section data-account-panel="addresses" hidden><div class="section-head"><h2>Saved addresses</h2><button class="primary" data-address-add>Add an address</button></div>${addresses.length?addresses.map((a,i)=>`<article class="panel address-card"><h3>${esc(a.first+' '+a.last)}</h3><p>${esc(a.address)}<br>${esc(a.city)}, ${esc(a.state)} ${esc(a.pin)}</p><p>${esc(a.phone)} · ${esc(a.email)}</p><button data-address-edit="${i}">Edit</button><button class="inline-link" data-address-delete="${i}">Delete</button></article>`).join(''):'<p>No addresses saved on this device.</p>'}</section><section data-account-panel="profile" hidden><h2>Personal information</h2><p>${esc(p.name||'No name saved')}<br>${esc(p.email||'')}<br>${esc(p.phone||'')}</p><button class="primary" data-account-profile>Edit device-local profile</button><h3>WhatsApp account</h3><p>Not verified. OTP authentication requires the live store provider.</p><button data-login>Get account support</button></section><section data-account-panel="fit" hidden><h2>Your size profile</h2><p>Preferred size: ${esc(fit.size||'Not selected')}<br>Preferred fit: ${esc(fit.fit||'Not selected')}<br>Collection: ${esc(fit.collection||'Not selected')}</p><a class="button primary" href="/fit-profile/">Edit fit preferences</a></section><section data-account-panel="coupons" hidden><h2>A little extra for your edit.</h2><div class="coupon-cards"><div class="panel"><strong>SAVE100</strong><p>Preview ₹100 off ₹1,299 or more.</p><button data-copy="SAVE100">Copy code</button></div><div class="panel"><strong>STYLE300</strong><p>Preview ₹300 off ₹2,499 or more.</p><button data-copy="STYLE300">Copy code</button></div></div><p>Final offers are confirmed by the live store.</p></section><section data-account-panel="support" hidden><h2>Here for your next step.</h2><p>Discuss a return, exchange, fit concern or delivery question with our team.</p><a class="button primary" href="/returns/">Return / exchange enquiry</a><a class="button" href="/support/">Order support</a><a class="text-link" href="/contact/">Contact our team</a></section></div></div></div>`};
function selectAccountTab(tab){document.querySelectorAll('[data-account-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.accountTab===tab));document.querySelectorAll('[data-account-panel]').forEach(p=>p.hidden=p.dataset.accountPanel!==tab)}
function addressModal(index){const as=readLocal('addresses',[]),a=as[index]||{};openOverlay(index===undefined?'Add a delivery address.':'Edit your address.',`<form id="address-form" class="stack" data-address-index="${index??''}"><div class="form-grid">${field('First name','first','text',true)}${field('Last name','last','text',true)}${field('Email','email','email',true)}${field('Mobile','phone','tel',true,'pattern="[6-9][0-9]{9}"')}${field('Street address','address','text',true,'class="full"')}${field('City','city','text',true)}${field('State','state','text',true)}${field('PIN code','pin','text',true,'pattern="[1-9][0-9]{5}"')}</div><p class="muted">Saved on this device only.</p><button class="primary">Save address</button></form>`);for(const [k,v] of Object.entries(a)){const x=$('#address-form').elements.namedItem(k);if(x)x.value=v}}
function comparePage(){let ids=readLocal('compare',[]),list=ids.map(id=>products.find(p=>p.id===id)).filter(Boolean);return `<div class="wrap">${heading('A thoughtful comparison.','Compare up to four styles side by side.')}<div class="notice">Prices and stock are from the supplied catalogue. Measurements and fabric composition should be confirmed per product.</div><section>${list.length?`<div class="compare-grid" style="--compare-count:${list.length}">${list.map(p=>`<article class="compare-card"><button class="inline-link" data-compare-remove="${p.id}">Remove ×</button>${img(p)}<h2>${esc(p.name)}</h2><strong>${money(p.price)}</strong><dl><dt>Category</dt><dd>${p.category}</dd><dt>Colour from title</dt><dd>${esc(p.color)}</dd><dt>Available size labels</dt><dd>${p.variants.filter(v=>v.stock).map(v=>esc(v.size)).join(' · ')}</dd><dt>Availability</dt><dd>${available(p)?'Available in catalogue':'Ask the team'}</dd></dl><button class="primary" data-quick-add="${p.id}">Choose size</button><a class="text-link" href="/product/${p.slug}/">Full details</a></article>`).join('')}</div>`:'<div class="empty"><h2>A little help deciding.</h2><p>Open a product and choose Compare to add it here.</p><a class="button primary" href="/shop/">Explore styles</a></div>'}</section></div>`}
function supportPage(type='support'){return `<div class="wrap">${heading(type==='returns'?'Let’s help with your next step.':'Order support, from a real person.',type==='returns'?'Prepare a return or exchange enquiry for our support team.':'Have a question about an order? Share the details with Beyond.')}<div class="split content"><div><h2>We’re here to help.</h2><p>Keep your order number and product details nearby. Our team can review the request and explain the applicable store policy.</p><div class="notice">This form prepares a WhatsApp message. It does not approve a return, issue a refund or create a live support ticket.</div><a class="text-link" href="/return-policy/">Read return & exchange information</a></div><form class="panel stack" id="support-form">${field('Order reference','order','text',true)}${field('Your name','name','text',true)}<label class="field">Request type<select name="type"><option>Size / fit advice</option><option ${type==='returns'?'selected':''}>Exchange request</option><option>Return request</option><option>Delivery enquiry</option><option>Wrong / damaged item</option><option>Other</option></select></label><label class="field">Tell us more<textarea name="message" required minlength="10"></textarea></label><button class="primary">Prepare WhatsApp enquiry</button><div id="support-ready"></div></form></div></div>`}
function trackPage(){return `<div class="wrap">${heading('Your order, one clear view.','Find a demo order saved on this device, or contact support about a real order.')}<div class="article content"><form id="track-form" class="panel stack">${field('Order reference','order','text',true)}<button class="primary">View demo order status</button></form><div id="track-result"></div><p>Live courier tracking requires the connected WooCommerce store and shipping provider.</p><a class="text-link" href="${wa('Hi Beyond, I need to track a real order.')}" target="_blank" rel="noopener">Ask about a real order on WhatsApp</a></div></div>`}
function trackingResult(id){const o=readLocal('orders',[]).find(o=>o.id===id.trim());$('#track-result').innerHTML=o?`<div class="panel tracking-status"><span class="status-pill soon">Demo order saved</span><h2>${esc(o.id)}</h2><p>${new Date(o.date).toLocaleDateString('en-IN')} · ${money(o.total)}</p><p>No payment collected. No real order or shipment exists.</p><a class="button" href="/order-confirmation/?order=${encodeURIComponent(o.id)}">View demo order details</a></div>`:'<div class="notice">No matching demo order is saved on this device. Contact the team for live order enquiries.</div>'}
wishlistPage=function(){let list=products.filter(p=>wishlist.includes(p.id));return `<div class="wrap">${heading('A little collection of things you love.','Saved on this device, ready when you are.')}<div class="wishlist-toolbar"><span>${list.length} saved styles</span><button data-share-wishlist ${!list.length?'disabled':''}>Share your wishlist</button></div><section>${list.length?`<div class="product-grid">${list.map(card).join('')}</div><p class="muted">Choose a size to move a favourite into your bag. Live price-drop and sale alerts require the connected store.</p>`:'<div class="empty"><h2>Your next favourite is waiting.</h2><p>Tap a heart on a product to save it here.</p><a class="button primary" href="/shop/">Explore your style</a></div>'}</section></div>`};
const oldReviewList=reviewList;
reviewList=function(id){let rs=reviews.filter(r=>!id||r.product===id);return rs.length?rs.map((r,i)=>`<article class="review enhanced-review" data-rating="${r.rating}"><div><strong>${esc(r.name)}</strong><span>${'★'.repeat(Number(r.rating))}</span></div><p>${esc(r.text)}</p><small>Size: ${esc(r.size||'Not specified')} · Fit: ${esc(r.fit||'Not specified')}</small>${r.image?`<img class="review-photo" src="${esc(r.image)}" alt="Customer review photo">`:''}<div class="review-bottom"><small>Unverified preview review · saved on this device</small><button class="inline-link" data-helpful="${reviews.indexOf(r)}">Helpful (${Number(r.helpful)||0})</button></div></article>`).join(''):'<div class="empty review-empty"><h3>Your experience can help someone else.</h3><p>No published reviews are available in this preview. Tell us how the fit felt.</p></div>'};
reviewPage=function(){const product=new URLSearchParams(location.search).get('product')||'';const rs=reviews.filter(r=>!product||r.product===product);return `<div class="wrap">${heading('Honest feedback. Better fit.','Share your experience and help another shopper find their fit.')}<div class="notice">Reviews here are unverified, device-local previews. Verified purchases and moderation require the live store.</div><div class="split content"><div><div class="rating-breakdown"><div><strong>${rs.length?(rs.reduce((n,r)=>n+Number(r.rating),0)/rs.length).toFixed(1):'—'}</strong><span>${rs.length} preview reviews</span></div><div>${[5,4,3,2,1].map(n=>`<div class="rating-line"><span>${n} ★</span><progress max="${Math.max(1,rs.length)}" value="${rs.filter(r=>Number(r.rating)===n).length}"></progress><span>${rs.filter(r=>Number(r.rating)===n).length}</span></div>`).join('')}</div></div><label class="review-filter">Filter reviews <select id="review-rating-filter"><option value="">All ratings</option>${[5,4,3,2,1].map(n=>`<option value="${n}">${n} stars</option>`).join('')}</select></label><div id="review-list">${reviewList(product||null)}</div></div><form id="lux-review-form" class="panel stack"><h2>How did it fit?</h2>${field('Your name','name','text',true)}<label class="field">Product<select name="product" required><option value="">Choose a product</option>${products.map(p=>`<option value="${p.id}" ${p.id===product?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div class="form-grid"><label class="field">Rating<select name="rating">${[5,4,3,2,1].map(n=>`<option value="${n}">${n} stars</option>`).join('')}</select></label><label class="field">Size purchased<input name="size" placeholder="e.g. 3XL"></label></div><label class="field">Fit feedback<select name="fit"><option>True to size</option><option>Smaller than expected</option><option>Larger than expected</option><option>Not sure</option></select></label><label class="field">Your review<textarea name="text" required minlength="10" maxlength="2000"></textarea></label><label class="field">Photo (optional)<input type="file" accept="image/jpeg,image/png,image/webp" name="photo"><small>Saved on this device only. Maximum 2 MB.</small></label><button class="primary">Save preview review</button></form></div></div>`};
function recentPage(){const ps=readLocal('recent',[]).map(id=>products.find(p=>p.id===id)).filter(Boolean);return `<div class="wrap">${heading('Still thinking about it?','Your recently viewed styles, saved on this device.')}<section>${ps.length?`<div class="product-grid">${ps.map(card).join('')}</div><button class="inline-link" data-clear-recent-products>Clear recently viewed</button>`:'<div class="empty"><h2>Your story starts with a style.</h2><a class="button primary" href="/shop/">Explore the collection</a></div>'}</section></div>`}
const newPolicyData={'international-shipping-policy':['International shipping','International delivery destinations, charges, customs and import duties have not been confirmed for this preview. Contact Beyond before placing an international order. No international order or shipment is created here.'],'disclosure-policy':['Disclosure policy','Product details are drawn from the supplied WooCommerce export. Collection edits are editorial selections and do not claim measured sales popularity. Colour names are inferred from product titles. Supplied website testimonials are not verified purchases in this preview.'],'refund-policy':['Refund information','Contact the store with your order details to discuss eligibility. Refund approval, payment method and processing time require the final store policy and payment provider. This preview collects no payments and processes no refunds.']};
for(const [k,[title,description]]of Object.entries(newPolicyData))policies[k]={title,sections:[['Store information',description],['Contact Beyond','Email Support@beyondplussize.in or WhatsApp +91 8318595521. Final policies should be reviewed before transactions are enabled.']]};
const oldFooter=footer;
footer=function(title){let html=oldFooter(title).replace('A little more Beyond.','Stay in the Beyond.').replace('New collections, style notes and fit inspiration.','Get collection inspiration, exclusive offer news and store updates.').replace('Join the preview list','Join Beyond');html=html.replace('<a href="/about/">Our story</a>','<a href="/new-arrivals/">New arrivals edit</a><a href="/best-sellers/">Bestsellers edit</a><a href="/stores/">Store locator</a><a href="/about/">Our story</a>');html=html.replace('<a href="/terms-and-conditions/">Terms & conditions</a>','<a href="/refund-policy/">Refund information</a><a href="/international-shipping-policy/">International shipping</a><a href="/disclosure-policy/">Disclosure</a><a href="/terms-and-conditions/">Terms & conditions</a>');html+=`<a class="floating-whatsapp" href="${wa(currentProduct?'Hi Beyond, I need help with '+currentProduct.name+'. Size: '+selectedVariant.size:'Hi Beyond, I would like some shopping assistance.')}" target="_blank" rel="noopener" aria-label="Chat with Beyond on WhatsApp"><svg viewBox="0 0 24 24"><path d="M20 11.5a8.5 8.5 0 0 1-12.7 7.4L3 20l1.1-4.3A8.5 8.5 0 1 1 20 11.5Z"/><path d="M8 7.5c0 4.2 3.2 7.4 7.4 7.4l1-2-2.2-1-1 1c-1.3-.6-2.3-1.7-3-3l1-1-1-2.2L8 7.5Z"/></svg></a><nav class="mobile-bottom-nav" aria-label="Mobile shopping navigation">${[['Home','/','home'],['Shop','/shop/','search'],['Wishlist','/wishlist/','heart'],['Account','/account/','user'],['Bag','/cart/','bag']].map(([t,u,k])=>`<a href="${u}" ${k==='bag'?'data-open-bag':''} class="${location.pathname===u?'active':''}"><svg viewBox="0 0 24 24">${k==='home'?'<path d="m3 10 9-7 9 7v11H3V10Z"/><path d="M9 21v-8h6v8"/>':icons[k]}</svg><span>${t}</span></a>`).join('')}</nav>`;return html};
const baseRender=render;
render=function(){closeOverlay();clearInterval(slideTimer);revealObserver?.disconnect();const path=location.pathname.replace(/\/$/,'')||'/';const routes={'/stores':['Store locator',storesPage],'/store-locator':['Store locator',storesPage],'/collections':['Featured collections',collectionPage],'/shop-by-size':['Shop by size',sizeShop],'/fit-profile':['Your fit profile',fitProfilePage],'/compare':['Compare styles',comparePage],'/recently-viewed':['Recently viewed',recentPage],'/returns':['Returns & exchange support',()=>supportPage('returns')],'/support':['Order support',()=>supportPage()],'/track-order':['Track order',trackPage],'/new-arrivals':['New arrivals edit',()=>shop('New arrivals edit')],'/best-sellers':['Bestsellers edit',()=>shop('Bestsellers edit')],'/order-confirmation':['Demo order details',()=>{const id=new URLSearchParams(location.search).get('order');const o=readLocal('orders',[]).find(o=>o.id===id);return o?orderConfirmation(o):`<div class="wrap content"><div class="empty"><h2>No matching demo order.</h2><a class="button primary" href="/account/">View preview account</a></div></div>`}]};if(routes[path]){currentProduct=null;const [title,fn]=routes[path];$('#app').innerHTML=header()+`<main id="main">${fn()}</main>`+footer(title);document.title=title+' | Beyond Plus Size';$('meta[name=description]').content=seoCopy(title);$('meta[property="og:title"]').content=document.title;$('meta[property="og:description"]').content=seoCopy(title);$('meta[property="og:url"]').content=location.origin+location.pathname;$('link[rel=canonical]').href=location.origin+location.pathname;updateSchema(title);if($('#results'))updateResults()}else baseRender();enhancePage();};
const originalSchema=updateSchema;
updateSchema=function(title){originalSchema(title);const node=$('#schema');let pageSchema=JSON.parse(node.textContent);let breadcrumb={"@context":"https://schema.org","@type":"BreadcrumbList",itemListElement:[{"@type":"ListItem",position:1,name:'Home',item:location.origin+'/'},{"@type":"ListItem",position:2,name:title,item:location.origin+location.pathname}]};const org={"@context":"https://schema.org","@type":"Organization",name:'Beyond The Plus Size Store',logo:location.origin+'/assets/logo.png',url:location.origin,telephone:'+918318595521',email:'Support@beyondplussize.in',sameAs:['https://www.instagram.com/beyondplussizeofficial/','https://www.facebook.com/profile.php?id=61577006312648']};let schema=[pageSchema,breadcrumb,org];if(location.pathname.startsWith('/stores'))for(const s of storeData.filter(s=>s.status==='open'))schema.push({'@context':'https://schema.org','@type':'ClothingStore',name:'Beyond · '+s.name,address:s.address,telephone:'+91'+s.phone,url:location.origin+'/stores/?store='+s.id});if(location.pathname.startsWith('/faq'))schema.push({'@context':'https://schema.org','@type':'FAQPage',mainEntity:faqData.map(([q,a])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:a}}))});node.textContent=JSON.stringify(schema)};
function enhancePage(){startSlides();if('IntersectionObserver'in window){revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');revealObserver.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el))}else document.querySelectorAll('.reveal').forEach(el=>el.classList.add('visible'));if($('#lux-checkout')){restoreCheckout();track('begin_checkout')}if(currentProduct){let start=0;$('.main-image-button').addEventListener('touchstart',e=>start=e.touches[0].clientX,{passive:true});$('.main-image-button').addEventListener('touchend',e=>{let diff=e.changedTouches[0].clientX-start;if(Math.abs(diff)>45)productPhoto(Number($('.main-image-button').dataset.galleryIndex||0)+(diff<0?1:-1))},{passive:true})}if($('#track-form')){let id=new URLSearchParams(location.search).get('order');if(id){$('#track-form').elements.order.value=id;trackingResult(id)}}if(location.pathname==='/account/'&&new URLSearchParams(location.search).get('tab'))selectAccountTab(new URLSearchParams(location.search).get('tab'));updateScrollUI();}
function updateScrollUI(){const h=$('#lux-header');h?.classList.toggle('compact-header',window.scrollY>30);const bar=$('#sticky-purchase');if(bar){const purchase=$('#main-purchase');const visible=purchase&&purchase.getBoundingClientRect().bottom<100;bar.classList.toggle('visible',visible)} }
window.addEventListener('scroll',updateScrollUI,{passive:true});
function copyText(text){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>toast('Copied.')).catch(()=>copyFallback(text));else copyFallback(text)}
function copyFallback(text){openOverlay('Copy and share.',`<label class="field">Link or message<textarea readonly>${esc(text)}</textarea></label><p>Select and copy the text above.</p>`)}
function shareProduct(id){const p=products.find(p=>p.id===id),url=location.origin+'/product/'+p.slug+'/';if(navigator.share)navigator.share({title:p.name,url}).catch(()=>{});else copyText(url)}
function addCompare(id){let ids=readLocal('compare',[]);if(ids.includes(id)){toast('Already in your comparison.');return}if(ids.length>=4){toast('Compare up to four styles. Remove one first.');return}writeLocal('compare',[...ids,id]);openOverlay('A little help deciding.',`<p>This style is now in your comparison.</p><a class="button primary" href="/compare/">Compare ${ids.length+1} styles</a><button data-close>Keep browsing</button>`)}
