document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#beyond-dialog'))closeOverlay();closeFilter();$('#mobile-nav')?.classList.remove('open');$('#menu-toggle')?.setAttribute('aria-expanded','false')}if($('#gallery-photo')){if(e.key==='ArrowRight')showGalleryImage(galleryIndex+1);if(e.key==='ArrowLeft')showGalleryImage(galleryIndex-1)}if(e.key==='Enter'&&e.target.id==='overlay-search'){rememberSearch(e.target.value);e.preventDefault()}});
